        n = len(grid)
        size = 4 * n * n
        parent = list(range(size))
        rank = [0] * size
        count = size

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for i in range(n):
            row = grid[i]
            for j in range(n):
                base = 4 * (i * n + j)
                ch = row[j]
                if ch == '/':
                    unions = ((base, base + 3), (base + 1, base + 2))
                elif ch == '\\':
                    unions = ((base, base + 1), (base + 2, base + 3))
                else:
                    unions = ((base, base + 1), (base + 1, base + 2), (base + 2, base + 3))

                if i + 1 < n:
                    nb = base + 4 * n
                    unions += ((base + 2, nb),)
                if j + 1 < n:
                    nb = base + 4
                    unions += ((base + 1, nb + 3),)

                for a, b in unions:
                    ra, rb = find(a), find(b)
                    if ra != rb:
                        if rank[ra] < rank[rb]:
                            ra, rb = rb, ra
                        parent[rb] = ra
                        if rank[ra] == rank[rb]:
                            rank[ra] += 1
                        count -= 1

        return count
